import{_ as o,C as r,o as l,c as i,j as a,a as s,E as n,a2 as d}from"./chunks/framework.B-bxTAy7.js";const f=JSON.parse('{"title":"隐私与免责","description":"这个站点收集什么、不收集什么：无后端、无 Cookie、无第三方脚本，localStorage 只存主题偏好；附强电安全免责声明。","frontmatter":{"title":"隐私与免责","description":"这个站点收集什么、不收集什么：无后端、无 Cookie、无第三方脚本，localStorage 只存主题偏好；附强电安全免责声明。","outline":[2]},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1792474335000}'),c={name:"guide/privacy.md"};function h(p,e,u,g,_,b){const t=r("Meta");return l(),i("div",null,[e[0]||(e[0]=a("h1",{id:"隐私与免责",tabindex:"-1"},[s("隐私与免责 "),a("a",{class:"header-anchor",href:"#隐私与免责","aria-label":'Permalink to "隐私与免责"'},"​")],-1)),n(t,{time:"2 min",level:"指南",note:"一个纯静态站点的隐私说明可以很短，这里把它写全"}),e[1]||(e[1]=d('<h2 id="数据收集-没有" tabindex="-1">数据收集：没有 <a class="header-anchor" href="#数据收集-没有" aria-label="Permalink to &quot;数据收集：没有&quot;">​</a></h2><p>这个站是<strong>纯静态站点</strong>：全部页面在构建期生成后丢到静态托管上，没有后端服务器、没有数据库、没有账号系统。访问本站时：</p><ul><li><strong>不留姓名与联系方式</strong>——没有注册、登录、留言表单，想联系作者请走 GitHub issue（见<a href="./about">关于与版权</a>）；</li><li><strong>不用 Cookie</strong>——站点自身不设置任何 Cookie；</li><li><strong>不加载第三方脚本</strong>——没有统计（Analytics）、没有广告、没有字体/CDN 外链，页面引用的全部资源都随站点同源部署；</li><li><strong>不追踪访问者</strong>——没有埋点，没有指纹采集，服务器侧如果有访问日志，也归静态托管平台（如 GitHub Pages / Cloudflare Pages）的默认策略管，与本站无关。</li></ul><h2 id="localstorage-的用途" tabindex="-1">localStorage 的用途 <a class="header-anchor" href="#localstorage-的用途" aria-label="Permalink to &quot;localStorage 的用途&quot;">​</a></h2><p>唯一的本地存储是 VitePress 默认主题写入的一个键：</p><table tabindex="0"><thead><tr><th>键</th><th>内容</th><th>用途</th></tr></thead><tbody><tr><td><code>vitepress-theme-appearance</code></td><td><code>light</code> / <code>dark</code> / <code>auto</code></td><td>记住你选的浅色 / 深色外观</td></tr></tbody></table><p>它只保存在你自己的浏览器里，不上传、不同步、不参与任何统计。清除浏览器站点数据即可删除。</p><p>搜索索引（本地搜索用的）在浏览器内存里完成检索，关键词不会发往任何服务器。</p><h2 id="强电安全免责" tabindex="-1">强电安全免责 <a class="header-anchor" href="#强电安全免责" aria-label="Permalink to &quot;强电安全免责&quot;">​</a></h2><p>本站内容用于<strong>学习与复习</strong>，不能替代教材、课程标准或工程规范。特别提醒：</p><ul><li>涉及<strong>强电操作</strong>（220 V 市电、三相电、电机控制）的内容仅为原理讲解，实操必须遵守现行国家标准（GB）与设备手册，在具备资质和断电、验电、放电等安全措施的条件下进行；</li><li>器件选型、参数计算、安全距离等数据请以厂商数据手册与最新国标为准，本站例题数字只为教学演示做了简化；</li><li>依据本站内容进行实验、施工或设备改造造成的任何人身与财产损失，本站不承担责任。</li></ul><h2 id="版权" tabindex="-1">版权 <a class="header-anchor" href="#版权" aria-label="Permalink to &quot;版权&quot;">​</a></h2><p>正文与图示 CC BY-NC-SA 4.0，代码 MIT，教材来源与引用格式见<a href="./about">关于与版权</a>。</p>',13))])}const C=o(c,[["render",h]]);export{f as __pageData,C as default};
